package com.aivideogenerator.app.domain.models\n\nimport java.io.Serializable\nimport java.util.Date\n\ndata class VideoProject(\n    val id: String,\n    val title: String,\n    val description: String,\n    val scenes: List<Scene>,\n    val duration: Long, // in milliseconds\n    val aspectRatio: AspectRatio = AspectRatio.RATIO_16_9,\n    val fps: Int = 30,\n    val createdAt: Date,\n    val updatedAt: Date,\n    val thumbnailPath: String? = null,\n    val status: ProjectStatus = ProjectStatus.DRAFT\n) : Serializable\n\ndata class Scene(\n    val id: String,\n    val index: Int,\n    val duration: Long, // in milliseconds\n    val narration: String,\n    val images: List<ImageClip>,\n    val backgroundMusic: AudioClip? = null,\n    val subtitles: List<Subtitle> = emptyList(),\n    val transitions: TransitionEffect = TransitionEffect.FADE,\n    val digitialAnchor: DigitalAnchorSettings? = null\n) : Serializable\n\ndata class ImageClip(\n    val id: String,\n    val imagePath: String,\n    val duration: Long, // in milliseconds\n    val startTime: Long = 0,\n    val scale: Float = 1f,\n    val rotation: Float = 0f,\n    val brightness: Float = 1f,\n    val contrast: Float = 1f,\n    val saturation: Float = 1f,\n    val zoomStart: Float = 1f,\n    val zoomEnd: Float = 1f,\n    val xPosition: Float = 0.5f,\n    val yPosition: Float = 0.5f\n) : Serializable\n\ndata class AudioClip(\n    val id: String,\n    val audioPath: String,\n    val startTime: Long = 0,\n    val volume: Float = 1f,\n    val fadeInDuration: Long = 0,\n    val fadeOutDuration: Long = 0\n) : Serializable\n\ndata class Subtitle(\n    val id: String,\n    val text: String,\n    val startTime: Long,\n    val endTime: Long,\n    val fontSize: Int = 28,\n    val fontFamily: String = \"sans-serif\",\n    val color: Int = 0xFFFFFF,\n    val backgroundColor: Int? = null,\n    val xPosition: Float = 0.5f,\n    val yPosition: Float = 0.85f,\n    val alignment: TextAlignment = TextAlignment.CENTER\n) : Serializable\n\ndata class DigitalAnchorSettings(\n    val enabled: Boolean = false,\n    val avatarPath: String? = null,\n    val voiceUrl: String? = null,\n    val animationStyle: AnchorAnimationStyle = AnchorAnimationStyle.TALKING,\n    val position: AnchorPosition = AnchorPosition.BOTTOM_RIGHT,\n    val scale: Float = 0.3f\n) : Serializable\n\ndata class TransitionEffect(\n    val type: TransitionType = TransitionType.FADE,\n    val duration: Long = 300, // in milliseconds\n    val interpolation: InterpolationType = InterpolationType.EASE_IN_OUT\n) : Serializable\n\nenum class ProjectStatus {\n    DRAFT, PROCESSING, COMPLETED, FAILED, EXPORTING\n}\n\nenum class AspectRatio(val width: Int, val height: Int) {\n    RATIO_16_9(16, 9),\n    RATIO_9_16(9, 16),\n    RATIO_1_1(1, 1),\n    RATIO_21_9(21, 9)\n}\n\nenum class TransitionType {\n    FADE, SLIDE_LEFT, SLIDE_RIGHT, SLIDE_UP, SLIDE_DOWN, ZOOM, WIPE\n}\n\nenum class InterpolationType {\n    LINEAR, EASE_IN, EASE_OUT, EASE_IN_OUT, BOUNCE\n}\n\nenum class TextAlignment {\n    LEFT, CENTER, RIGHT\n}\n\nenum class AnchorAnimationStyle {\n    TALKING, GESTURING, IDLE, EXCITED\n}\n\nenum class AnchorPosition {\n    TOP_LEFT, TOP_CENTER, TOP_RIGHT,\n    CENTER_LEFT, CENTER, CENTER_RIGHT,\n    BOTTOM_LEFT, BOTTOM_CENTER, BOTTOM_RIGHT\n}\n"